function test_staleSstoreValueAfterActivation() public {
    // This test requires deploying on a chain without initial tstore support
    // Deploy AMMStandardHook where _tstoreInitialSupport = false
    // _setTstorish uses sstore fallback

    // Transaction 1: Direct swap beforeSwap writes via sstore
    // Slot 0xFFFFFFFFFFFFFFFF now has value X in persistent storage
    // Transaction completes normally (afterSwap reads via sload, correct)

    // Transaction 2: Enable tstore support on chain (fork upgrade)
    // Call __activateTstore()
    // _onTstoreSupportActivated: tstore(SLOT, sload(SLOT))
    // tstore now has value X (stale from transaction 1)
    // sload still has value X (never cleared)

    // Transaction 3: New direct swap
    // beforeSwap: _setTstorish now uses tstore (tstoreSupport=true)
    // Writes fresh value Y to tstore
    // afterSwap: _getTstorish reads from tload, gets Y (correct)
    // But slot 0xFFFFFFFFFFFFFFFF in sstore still has X (gas waste)

    // The stale sstore value is never cleared:
    uint256 staleValue;
    assembly { staleValue := sload(0xFFFFFFFFFFFFFFFF) }
    assertTrue(staleValue != 0); // Stale value persists
}

