function test_cumulativeRoundingCausesFillRevert() public {
    // Setup: Order book with 500 tiny orders at same price
    // minimumOrderBase=1, minimumOrderScale=0 -> minimum=1 wei
    // Each order: inputAmount = 3 wei (small to maximize rounding per unit)
    // Price: sqrtPriceX96 = Q96 + 1 (maximizes rounding in mulDivRoundingUp)

    uint160 price = uint160((1 << 96) + 1);
    for (uint i = 0; i < 500; i++) {
        clob.openOrder(tokenIn, tokenOut, price, 3, groupKey, 0, hookData);
    }

    // Total input = 500 * 3 = 1500 wei
    // Bulk output = calculateFixedInput(1500, price)
    // Per-order output sum = sum_{i=1..500}(calculateFixedInput(3, price))
    // Each step: ceil(ceil(3 * (Q96+1) / Q96) * (Q96+1) / Q96)
    //          = ceil(ceil(3 + 3/Q96) * (Q96+1) / Q96)
    //          = ceil(4 * (Q96+1) / Q96)
    //          = ceil(4 + 4/Q96) = 5 wei
    // Total per-order sum = 500 * 5 = 2500 wei
    // Bulk = ceil(ceil(1500 * (Q96+1) / Q96) * (Q96+1) / Q96)
    //       = ceil(ceil(1500 + 1500/Q96) * (Q96+1) / Q96)
    //       = ceil(1501 * (Q96+1) / Q96)
    //       = ceil(1501 + 1501/Q96) = 1502 wei
    // Drift = 2500 - 1502 = 998 wei!
    // If AMM provides outputAmount = 1502, fill reverts at step ~300

    vm.expectRevert(CLOBTransferHandler__InsufficientOutputToFill.selector);
    // ... execute swap that triggers fill ...
}

function test_feeOnTransferActivatedAfterDeposit() public {
    // Setup: Deploy fee-toggleable token (e.g., with setFee function)
    FeeToggleToken token = new FeeToggleToken();
    token.setFee(0); // No fee initially

    // Deposit tokens into CLOB (passes balance check)
    token.approve(address(clob), 1000e18);
    clob.depositToken(address(token), 1000e18);
    assertEq(clob.makerTokenBalance(address(token), address(this)), 1000e18);

    // Open CLOB order
    clob.openOrder(address(token), address(tokenOut), sqrtPrice, 500e18, groupKey, 0, hookData);

    // Token creator enables 5% fee
    token.setFee(500); // 5% fee on transfer

    // Attempt fill via AMM -> ammHandleTransfer
    // Line 296: safeTransfer sends 500e18 but AMM receives 475e18 (5% fee)
    // AMM line 2208: balanceBefore + 500e18 != balanceAfter (475e18 increase)
    // Reverts! All CLOB orders for this token are permanently bricked

    // Maker tries to withdraw remaining balance
    // Line 407: safeTransfer sends 500e18 but maker receives 475e18
    // No revert on withdraw (no balance check), but maker loses 5%
    // Insolvency: last withdrawer can't get their full balance
    clob.withdrawToken(address(token), 500e18);
    // Actual received: 475e18 (lost 25e18 to fee)
}

