function test_roundingDistortsPriceInValidateHandlerOrder() public {
    // Setup: Token with max pricing bound at sqrtPriceX96 = Q96 + 2
    // (just above 1:1 ratio)
    vm.startPrank(address(registry));
    address[] memory pairs = new address[](1);
    pairs[0] = address(tokenB);
    uint160[] memory mins = new uint160[](1);
    uint160[] memory maxs = new uint160[](1);
    maxs[0] = uint160((1 << 96) + 2); // Max just above 1:1
    hook.registryUpdatePricingBounds(address(tokenA), pairs, mins, maxs);
    vm.stopPrank();

    // Open order at sqrtPriceX96 = Q96 + 1 (within max bound)
    // orderAmount = 1 wei (tiny, maximizes rounding impact)
    // calculateFixedInput(1, Q96+1):
    //   step1 = mulDivRoundingUp(1, Q96+1, Q96) = 2
    //   step2 = mulDivRoundingUp(2, Q96+1, Q96) = 3
    // amountOut = 3

    // validateHandlerOrder computes price from (1, 3):
    // computeRatioX96(3, 1) = sqrt(3) * Q96 ≈ 1.73 * Q96
    // This exceeds max bound of Q96 + 2!
    // Order reverts despite declared sqrtPriceX96 being within bounds

    vm.expectRevert(AMMStandardHook__InvalidPrice.selector);
    clob.openOrder(
        address(tokenA), address(tokenB),
        uint160((1 << 96) + 1), // Within bounds
        1, // Tiny order -> rounding amplifies price
        groupKey, 0, hookData
    );
}
